{"verdicts": [
  {
    "id": "a",
    "claims": [
      {"claim": "The person is considering doing a small action tomorrow related to exercise or journaling.", "profile_fields": ["profile_summary"], "entailed": false},
      {"claim": "The person is being asked to choose one small action related to exercise or journaling to do tomorrow.", "profile_fields": ["profile_summary"], "entailed": false}
    ],
    "reason": "The question asks a hypothetical about a future action, not a current state or past fact about the person. It presupposes the person is considering these activities, which is not directly entailed by the profile."
  },
  {
    "id": "b",
    "claims": [
      {"claim": "The person wants to continue something.", "profile_fields": ["profile_summary"], "entailed": false},
      {"claim": "The person is being asked to define the smallest form of something they want to continue.", "profile_fields": ["profile_summary"], "entailed": false}
    ],
    "reason": "The question presupposes a desire to continue something, which is not explicitly stated in the profile. The profile states a desire to make exercise and journaling a habit, but not a general desire to 'continue something'."
  },
  {
    "id": "c",
    "claims": [
      {"claim": "The person is being asked if they have the余裕 (leeway/time) to reflect now.", "profile_fields": ["profile_summary"], "entailed": false},
      {"claim": "The person is being asked to identify which past goals felt heavy.", "profile_fields": ["profile_summary"], "entailed": false}
    ],
    "reason": "The question is conditional and asks about a hypothetical present state ('if you have the leeway to reflect now') and a past reflection, neither of which is directly supported by the profile."
  },
  {
    "id": "e",
    "claims": [
      {"claim": "The person often sets big goals and then gets discouraged.", "profile_fields": ["profile_summary"], "entailed": true}
    ],
    "reason": "The profile explicitly states '大きな目標を立てては挫折している' (often sets big goals and gets discouraged/fails)."
  },
  {
    "id": "f",
    "claims": [
      {"claim": "The person is being invited to leave a one-line memo of a step to take tomorrow.", "profile_fields": ["profile_summary"], "entailed": false}
    ],
    "reason": "This is an invitation or suggestion, not a factual claim about the person. It presupposes the person might be willing ('if you like'), but does not assert a current state or action."
  }
]}
